sp_ListarContasPagar	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarContasPagar`(IN p_idEmpresa INT)\nBEGIN\n\n    SELECT\n\n        cp.idContaPagar,\n\n        cp.idEmpresa,\n\n        cp.fornecedor_id,\n\n        cp.descricao,\n\n        cp.valorTotal,\n\n        cp.valorPago,\n\n        cp.dthVencimento,\n\n        cp.dthPagamento,\n\n        cp.dthCriacao,\n\n        cp.status,\n\n        cp.fAtivo,\n\n        f.NomeFantasia AS nomeFornecedor,\n\n        CASE\n\n            WHEN cp.valorPago >= cp.valorTotal THEN 'PAGO'\n\n            WHEN cp.dthVencimento < CURDATE() AND cp.valorPago < cp.valorTotal THEN 'VENCIDO'\n\n            ELSE 'ABERTO'\n\n        END AS statusAtual\n\n    FROM ContaPagar cp\n\n    LEFT JOIN Fornecedor f ON f.idFornecedor = cp.fornecedor_id\n\n    WHERE cp.idEmpresa = p_idEmpresa\n\n      AND cp.fAtivo = 1\n\n    ORDER BY cp.dthVencimento ASC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
